// SeizeLUT feature engine: the integer multimodal front end in the fabric (N10).
// A microcoded accumulator machine: one DW-bit adder, two 5-bit barrel shifters (no multiplier), a register file in
// block RAM and a program ROM generated by src/hw/fe_engine.py (rtl/fe/fe_rom.hex, rtl/fe/fe_ram.hex, rtl/fe/fe_io.vh).
// Every instruction takes 3 cycles (fetch, operand read, execute). The host writes inputs and reads features through
// the host port while the engine is idle, then starts a program at an entry (BIO, MOV, SEC, FLUSH) and waits for
// busy to fall. Instruction word: [31:27] op, [26:24] cond, [23] neg, [22] idx, [20:16] sh, [15:0] addr/target.
`timescale 1ns/1ps
module fe_engine #(
    parameter integer DW = 40,              // datapath width
    parameter integer AW = 10,              // register file address width (1,024 words)
    parameter integer PW = 12,              // program address width (4,096 instructions)
    parameter ROM_FILE = "fe_rom.hex",
    parameter RAM_FILE = "fe_ram.hex"
) (
    input  wire          clk,
    input  wire          rst,
    input  wire          start,             // pulse while idle: run the program at entry
    input  wire [PW-1:0] entry,
    output reg           busy,
    input  wire          host_we,           // host port, used while idle
    input  wire [AW-1:0] host_addr,
    input  wire [DW-1:0] host_wdata,
    output wire [DW-1:0] host_rdata         // ram[host_addr] one cycle after the address
);
    localparam [4:0] HALT = 5'd0, LD = 5'd1, ADD = 5'd2, ST = 5'd3, ASR = 5'd4, ABS = 5'd5, SAT = 5'd6, LOG2 = 5'd7,
                     MAX = 5'd8, J = 5'd10, BR = 5'd11, LDX = 5'd12, ADDABS = 5'd13;
    localparam [1:0] S_IDLE = 2'd0, S_FETCH = 2'd1, S_READ = 2'd2, S_EXEC = 2'd3;

    reg [31:0]   rom [0:(1<<PW)-1];
    reg [DW-1:0] ram [0:(1<<AW)-1];
    initial begin
        $readmemh(ROM_FILE, rom);
        $readmemh(RAM_FILE, ram);
    end

    reg [1:0]           state;
    reg [PW-1:0]        pc;
    reg [31:0]          rom_q, ir;
    reg [DW-1:0]        ram_q;
    reg signed [DW-1:0] A;
    reg [AW-1:0]        X, ea;

    // ---- decode of the instruction being read (rom_q) and of the one executing (ir)
    wire [AW-1:0] ea_c   = rom_q[AW-1:0] + (rom_q[22] ? X : {AW{1'b0}});
    wire [4:0]    op     = ir[31:27];
    wire [2:0]    cond   = ir[26:24];
    wire          neg    = ir[23];
    wire [4:0]    sh     = ir[20:16];
    wire [PW-1:0] target = ir[PW-1:0];

    // ---- single-port register file: host while idle, operand read, result write
    wire          ram_we   = (state == S_IDLE && host_we) || (state == S_EXEC && op == ST);
    wire [AW-1:0] ram_addr = (state == S_IDLE) ? host_addr : (state == S_EXEC) ? ea : ea_c;
    wire [DW-1:0] ram_wd   = (state == S_IDLE) ? host_wdata : A;
    always @(posedge clk) begin
        if (ram_we) ram[ram_addr] <= ram_wd;
        ram_q <= ram[ram_addr];
    end
    assign host_rdata = ram_q;
    always @(posedge clk) rom_q <= rom[pc];

    // ---- datapath
    wire signed [DW-1:0] opnd    = ram_q;
    wire signed [DW-1:0] opnd_sh = opnd <<< sh;
    wire signed [DW-1:0] term    = neg ? -opnd_sh : opnd_sh;
    wire signed [DW-1:0] opnd_abs = opnd[DW-1] ? -opnd : opnd;
    wire signed [DW-1:0] a_abs   = A[DW-1] ? -A : A;
    localparam signed [DW-1:0] SAT_HI = (1 <<< 19) - 1, SAT_LO = -(1 <<< 19);
    reg signed [DW-1:0] a_log;
    reg [DW-1:0]        a_small;
    reg [5:0]           lp;
    integer             k;
    always @(*) begin                         // integer log2 with 3 fraction bits (0 for A <= 0)
        lp = 6'd0;
        for (k = 0; k < DW; k = k + 1) if (A[k]) lp = k;
        a_small = A << (6'd3 - lp);
        if (A[DW-1] || A == 0) a_log = {DW{1'b0}};
        else if (lp >= 6'd3) a_log = {{(DW-9){1'b0}}, lp, A[lp-1 -: 3]};
        else a_log = {{(DW-9){1'b0}}, lp, a_small[2:0]};
    end
    reg take;
    always @(*) begin
        case (cond)
            3'd0: take = A < 0;
            3'd1: take = A >= 0;
            3'd2: take = A == 0;
            3'd3: take = A != 0;
            3'd4: take = A > 0;
            default: take = A <= 0;
        endcase
    end

    always @(posedge clk) begin
        if (rst) begin
            state <= S_IDLE; busy <= 1'b0; pc <= {PW{1'b0}}; X <= {AW{1'b0}}; A <= {DW{1'b0}};
        end else begin
            case (state)
                S_IDLE: if (start) begin pc <= entry; busy <= 1'b1; state <= S_FETCH; end
                S_FETCH: begin state <= S_READ; end                       // rom_q <= rom[pc]
                S_READ: begin ir <= rom_q; ea <= ea_c; pc <= pc + 1'b1; state <= S_EXEC; end   // ram_q <= ram[ea_c]
                S_EXEC: begin
                    state <= S_FETCH;
                    case (op)
                        HALT: begin busy <= 1'b0; state <= S_IDLE; end
                        LD: A <= term;
                        ADD: A <= A + term;
                        ASR: A <= A >>> sh;
                        ABS: A <= a_abs;
                        SAT: A <= (A > SAT_HI) ? SAT_HI : (A < SAT_LO) ? SAT_LO : A;
                        LOG2: A <= a_log;
                        MAX: A <= (opnd > A) ? opnd : A;
                        J: pc <= target;
                        BR: if (take) pc <= target;
                        LDX: X <= opnd[AW-1:0];
                        ADDABS: A <= A + opnd_abs;
                        default: ;                                         // ST: written above
                    endcase
                end
            endcase
        end
    end
endmodule
